from __future__ import annotations

import base64
import binascii
import json
from collections.abc import Sequence
from dataclasses import dataclass
from datetime import datetime
from typing import Any


@dataclass(frozen=True, slots=True)
class ActivityRow:
    """One activity-feed row."""

    created_at: datetime
    id: str
    payload: Any = None


def encode_cursor(row: ActivityRow) -> str:
    """Return an opaque cursor representing ``row``'s pagination key."""
    if not isinstance(row.created_at, datetime) or not isinstance(row.id, str):
        raise ValueError("invalid row pagination key")
    raw = json.dumps(
        [row.created_at.isoformat(), row.id],
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def decode_cursor(cursor: str) -> tuple[datetime, str]:
    """Decode a cursor or raise ``ValueError`` when it is malformed."""
    try:
        if not isinstance(cursor, str) or not cursor:
            raise ValueError("malformed cursor")
        if any(char not in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_=" for char in cursor):
            raise ValueError("malformed cursor")
        padded = cursor + "=" * (-len(cursor) % 4)
        data = base64.b64decode(padded, altchars=b"-_", validate=True)
        value = json.loads(data.decode("utf-8"))
        if not isinstance(value, list) or len(value) != 2:
            raise ValueError("malformed cursor")
        created_at = datetime.fromisoformat(value[0]) if isinstance(value[0], str) else None
        if created_at is None or not isinstance(value[1], str):
            raise ValueError("malformed cursor")
        return created_at, value[1]
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError, binascii.Error, OverflowError) as exc:
        raise ValueError("malformed cursor") from exc


def page_after(
    rows: Sequence[ActivityRow],
    cursor: str | None,
    limit: int,
) -> tuple[list[ActivityRow], str | None]:
    """Return the next ascending page and a cursor when more rows remain."""
    if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
        raise ValueError("limit must be a positive integer")

    ordered = sorted(rows, key=lambda row: (row.created_at, row.id))
    start = 0
    if cursor is not None:
        boundary = decode_cursor(cursor)
        while start < len(ordered) and (ordered[start].created_at, ordered[start].id) <= boundary:
            start += 1

    page = ordered[start : start + limit]
    end = start + len(page)
    next_cursor = encode_cursor(page[-1]) if page and end < len(ordered) else None
    return page, next_cursor
